    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <param name = "_inventDim">_salesLine</param>
    /// <returns>Result</returns>
    boolean salesLine_validateWrite(SalesLine _salesLine, InventDim _inventDim)
    {
        boolean ret = true;

        if(!_salesLine.RecId)
        {
            // MPJ-21310 Item substitutions
            // TODO this is probably better at itemID.modified (UI)
            var itemSub = new METSalesItemSubstitution(_salesLine, _inventDim);
            ret = itemSub.checkSalesLineAtCreation();            
        }

        ret = next salesLine_validateWrite(_salesLine, _inventDim) && ret;
        return ret;
    }

/// <summary>
/// CoC
/// </summary>
/// <returns>Result</returns>
public boolean useAlternativeItem()
{
    boolean ret = next useAlternativeItem();
    ret = false;    // Use extended substitution logic in place of standard check. Possibly config to control this.
    return ret;
}
